package com.example.demo;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.validation.annotation.Validated; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api") @Validated
public class AhorroController {
 private final MetaAhorroRepository metas; private final MovimientoRepository movimientos;
 public AhorroController(MetaAhorroRepository metas, MovimientoRepository movimientos){this.metas=metas;this.movimientos=movimientos;}
 @GetMapping("/estado") public Map<String,String> estado(){return Map.of("app","Ahorra Joven API","estado","funcionando","version","1.0.0");}
 @GetMapping("/metas") public List<MetaAhorro> listarMetas(){return metas.findAll();}
 @GetMapping("/metas/{id}") public MetaAhorro obtenerMeta(@PathVariable Long id){return metas.findById(id).orElseThrow(()->new NoSuchElementException("No existe la meta con id "+id));}
 @PostMapping("/metas") public ResponseEntity<MetaAhorro> crearMeta(@Valid @RequestBody MetaAhorro meta){meta.setId(null);if(meta.getAhorrado()==null)meta.setAhorrado(BigDecimal.ZERO);MetaAhorro guardada=metas.save(meta);return ResponseEntity.status(HttpStatus.CREATED).body(guardada);}
 @PutMapping("/metas/{id}") public MetaAhorro actualizarMeta(@PathVariable Long id,@Valid @RequestBody MetaAhorro entrada){MetaAhorro m=obtenerMeta(id);m.setNombre(entrada.getNombre());m.setObjetivo(entrada.getObjetivo());m.setDescripcion(entrada.getDescripcion());m.setFechaObjetivo(entrada.getFechaObjetivo());return metas.save(m);}
 @DeleteMapping("/metas/{id}") public ResponseEntity<Void> eliminarMeta(@PathVariable Long id){MetaAhorro m=obtenerMeta(id);metas.delete(m);return ResponseEntity.noContent().build();}
 public record AporteRequest(@NotNull @DecimalMin(value="1.00") @Digits(integer=12,fraction=2) BigDecimal valor,@Size(max=120) String concepto,@NotNull LocalDate fecha) {}
 @PostMapping("/metas/{id}/aportes") public ResponseEntity<MetaAhorro> aportar(@PathVariable Long id,@Valid @RequestBody AporteRequest req){MetaAhorro m=obtenerMeta(id);m.setAhorrado(m.getAhorrado().add(req.valor()));MetaAhorro guardada=metas.save(m);Movimiento mov=new Movimiento();mov.setConcepto(req.concepto()==null||req.concepto().isBlank()?"Aporte a meta: "+m.getNombre():req.concepto());mov.setTipo(Movimiento.TipoMovimiento.APORTE);mov.setValor(req.valor());mov.setFecha(req.fecha());mov.setMetaId(id);movimientos.save(mov);return ResponseEntity.ok(guardada);}
 @GetMapping("/movimientos") public List<Movimiento> listarMovimientos(){return movimientos.findAllByOrderByFechaDescIdDesc();}
 @GetMapping("/movimientos/{id}") public Movimiento obtenerMovimiento(@PathVariable Long id){return movimientos.findById(id).orElseThrow(()->new NoSuchElementException("No existe el movimiento con id "+id));}
 @PostMapping("/movimientos") public ResponseEntity<Movimiento> crearMovimiento(@Valid @RequestBody Movimiento mov){mov.setId(null);if(mov.getFecha()==null)mov.setFecha(LocalDate.now());if(mov.getTipo()==Movimiento.TipoMovimiento.APORTE){if(mov.getMetaId()==null)throw new IllegalArgumentException("metaId es obligatorio para un APORTE");MetaAhorro m=obtenerMeta(mov.getMetaId());m.setAhorrado(m.getAhorrado().add(mov.getValor()));metas.save(m);}else if(mov.getMetaId()!=null&&!metas.existsById(mov.getMetaId()))throw new NoSuchElementException("No existe la meta con id "+mov.getMetaId());return ResponseEntity.status(HttpStatus.CREATED).body(movimientos.save(mov));}
 @DeleteMapping("/movimientos/{id}") public ResponseEntity<Void> eliminarMovimiento(@PathVariable Long id){Movimiento m=obtenerMovimiento(id);if(m.getTipo()==Movimiento.TipoMovimiento.APORTE&&m.getMetaId()!=null){metas.findById(m.getMetaId()).ifPresent(meta->{meta.setAhorrado(meta.getAhorrado().subtract(m.getValor()).max(BigDecimal.ZERO));metas.save(meta);});}movimientos.delete(m);return ResponseEntity.noContent().build();}
 @GetMapping("/resumen") public Map<String,Object> resumen(){List<Movimiento> lista=movimientos.findAll();BigDecimal ingresos=BigDecimal.ZERO,gastos=BigDecimal.ZERO,aportes=BigDecimal.ZERO;for(Movimiento m:lista){switch(m.getTipo()){case INGRESO->ingresos=ingresos.add(m.getValor());case GASTO->gastos=gastos.add(m.getValor());case APORTE->aportes=aportes.add(m.getValor());}}BigDecimal ahorrado=metas.findAll().stream().map(MetaAhorro::getAhorrado).reduce(BigDecimal.ZERO,BigDecimal::add);Map<String,Object> r=new LinkedHashMap<>();r.put("cantidadMetas",metas.count());r.put("cantidadMovimientos",movimientos.count());r.put("totalIngresos",ingresos);r.put("totalGastos",gastos);r.put("totalAportes",aportes);r.put("totalAhorradoEnMetas",ahorrado);r.put("balanceMovimientos",ingresos.subtract(gastos).subtract(aportes));return r;}
}
